<head>
<style>
  html,body{margin:0;padding:0;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;background:var(--viz-panel,#111827);color:var(--viz-text,#e5e7eb);font-family:system-ui,sans-serif;gap:8px;}
