<body>
<canvas id="c" width="360" height="480"></canvas>
<div class="hud">Score: <span id="score">0</span> &nbsp;|&nbsp; Lives: <span id="lives">3</span></div>
<button id="restart">Restart</button>
<div class="hint">Mouse / arrows / A D / touch to move paddle</div>
<script>
const canvas=document.getElementById('c');
const ctx=canvas.getContext('2d');
const W=canvas.width,H=canvas.height;
function T(n,f){const v=getComputedStyle(document.body).getPropertyValue(n).trim();return v||f;}
let paddle={w:80,h:12,x:W/2-40,y:H-30};
let ball={x:W/2,y:H/2,r:8,vx:3,vy:-4};
let score=0,lives=3,over=false;
const keys={};
function resetBall(){ball.x=W/2;ball.y=H/2;ball.vx=(Math.random()>0.5?3:-3);ball.vy=-4;}
function movePaddle(){if(keys['ArrowLeft']||keys['a']||keys['A'])paddle.x=Math.max(0,paddle.x-7);if(keys['ArrowRight']||keys['d']||keys['D'])paddle.x=Math.min(W-paddle.w,paddle.x+7);}
function update(){
  if(over)return;
  movePaddle();
  ball.x+=ball.vx;ball.y+=ball.vy;
  if(ball.x-ball.r<0){ball.x=ball.r;ball.vx=-ball.vx;}
  if(ball.x+ball.r>W){ball.x=W-ball.r;ball.vx=-ball.vx;}
  if(ball.y-ball.r<0){ball.y=ball.r;ball.vy=-ball.vy;}
  if(ball.y+ball.r>=paddle.y&&ball.y+ball.r<=paddle.y+paddle.h&&ball.x>=paddle.x&&ball.x<=paddle.x+paddle.w&&ball.vy>0){
    ball.vy=-Math.abs(ball.vy);
    const hit=(ball.x-(paddle.x+paddle.w/2))/(paddle.w/2);
    ball.vx=hit*5;score+=10;
    document.getElementById('score').textContent=score;
  }
  if(ball.y-ball.r>H){
    lives--;document.getElementById('lives').textContent=lives;
    if(lives<=0)over=true;else resetBall();
  }
}
function draw(){
  ctx.fillStyle=T('--viz-card','#1f2937');ctx.fillRect(0,0,W,H);
  ctx.fillStyle=T('--viz-accent','#6366f1');ctx.fillRect(paddle.x,paddle.y,paddle.w,paddle.h);
  ctx.beginPath();ctx.arc(ball.x,ball.y,ball.r,0,Math.PI*2);ctx.fillStyle=T('--viz-text','#e5e7eb');ctx.fill();
  if(over){ctx.fillStyle='rgba(0,0,0,0.55)';ctx.fillRect(0,0,W,H);ctx.fillStyle=T('--viz-text','#e5e7eb');ctx.textAlign='center';ctx.font='bold 26px system-ui';ctx.fillText('Game Over',W/2,H/2);ctx.font='14px system-ui';ctx.fillText('Click Restart to play again',W/2,H/2+26);ctx.textAlign='left';}
}
function loop(){update();draw();requestAnimationFrame(loop);}
loop();
