canvas.addEventListener('touchmove',e=>{e.preventDefault();const r=canvas.getBoundingClientRect();const s=W/r.width;const x=(e.touches[0].clientX-r.left)*s-paddle.w/2;paddle.x=Math.max(0,Math.min(W-paddle.w,x));},{passive:false});
document.addEventListener('keydown',e=>{keys[e.key]=true;});
document.addEventListener('keyup',e=>{keys[e.key]=false;});
